sites.find:
{
    for (y = 0; y < 16; ++y) {
        float row_v = (float)y * 0.0625f;
        float *entry_v = &grim_subrect_table[y * 16].v;
        for (x = 0; x < 16; entry_v += 2, ++x) {
            entry_v[-1] = (float)x * 0.0625f;
            entry_v[0] = row_v;
        }
    }
}

